export function isBlockVerseLayout(viewOptions) {
    return viewOptions?.verseLayout === "block";
}
/**
 * Get the class name list for the given view options.
 *
 * @param viewOptions - View options of the editor.
 * @returns the element class name list based on view options.
 *
 * @public
 */
export function getViewClassList(viewOptions) {
    const classList = [];
    const _viewOptions = viewOptions ?? defaultViewOptions;
    if (_viewOptions) {
        classList.push(`${MARKER_MODE_CLASS_NAME_PREFIX}${_viewOptions.markerMode}`);
        if (_viewOptions.hasSpacing)
            classList.push(TEXT_SPACING_CLASS_NAME);
        if (_viewOptions.isFormattedFont)
            classList.push(FORMATTED_FONT_CLASS_NAME);
    }
    return classList;
}
